with Src as (select * from departments where dept_name in ('Sales', 'Legal', 'Marketing') and (location is not null or dept_name is not null)), departments_stats as (select case when budget >= 3314000 then 'high' when budget >= 1034000 then 'mid' else 'low' end as budget_bucket, count(case when dept_name = 'HR' then 1 end) as hr_count, sum(budget) as total_budget from Src group by case when budget >= 3314000 then 'high' when budget >= 1034000 then 'mid' else 'low' end) select budget_bucket, total_budget from departments_stats where total_budget >= 24033000 order by total_budget asc
